mapper.delete:
DELETE FROM attendance_daily_summary
 WHERE emp_id = #{empId}
   AND work_date >= #{from, jdbcType=DATE}
   AND work_date <= #{to, jdbcType=DATE}

mapper.select:
SELECT emp_id, work_date, day_kind, pattern_id, contract_minutes, leave_kind, leave_minutes,
       work_start, work_end, break_minutes, worked_minutes, regular_minutes, extra_minutes, overtime_minutes,
       night_minutes, holiday_minutes, holiday_excess_minutes,
       overtime_rate, night_rate, holiday_rate, holiday_excess_rate,
       issues, calculated_by, calculated_at
  FROM attendance_daily_summary
 WHERE emp_id = #{empId}
   AND work_date >= #{from, jdbcType=DATE}
   AND work_date <= #{to, jdbcType=DATE}
 ORDER BY work_date

SELECT punch_type, punched_at, work_date
  FROM attendance_punch
 WHERE emp_id = #{empId}
   AND work_date >= #{from, jdbcType=DATE}
   AND work_date <= #{to, jdbcType=DATE}
 ORDER BY punched_at, punch_id
